    },
    ["MID-RANGE MOBILE"] = {
        acceptable = { coldVm = 75, warmP95 = 3, coldFrame = 75, coldFrameExcess = 20, frameP95 = 20, frameP95Excess = 3, frameP99 = 33.33, frameP99Excess = 6, hitch33Rate = 3, hitch33Excess = 2, hitch50Rate = 0.5, hitch50Excess = 0.4 },
        warning = { coldVm = 120, warmP95 = 6, coldFrame = 120, coldFrameExcess = 40, frameP95 = 33.33, frameP95Excess = 8, frameP99 = 50, frameP99Excess = 12, hitch33Rate = 8, hitch33Excess = 6, hitch50Rate = 2, hitch50Excess = 1.5 },
    },
    ["DESKTOP/PC"] = {
        acceptable = { coldVm = 50, warmP95 = 2, coldFrame = 50, coldFrameExcess = 15, frameP95 = 20, frameP95Excess = 2, frameP99 = 25, frameP99Excess = 4, hitch33Rate = 1, hitch33Excess = 0.75, hitch50Rate = 0.25, hitch50Excess = 0.2 },
        warning = { coldVm = 100, warmP95 = 4, coldFrame = 100, coldFrameExcess = 30, frameP95 = 25, frameP95Excess = 5, frameP99 = 33.33, frameP99Excess = 8, hitch33Rate = 4, hitch33Excess = 3, hitch50Rate = 1, hitch50Excess = 0.75 },
    },
}

assert(TIER_CRITERIA[DEVICE_TIER] ~= nil, "DEVICE_TIER is not recognized")

local function safeLuaMemoryKb()
    local ok, value = pcall(function()
        return collectgarbage("count")
    end)
    if ok and type(value) == "number" then
        return value
    end
    ok, value = pcall(function()
        return gcinfo()
    end)
    if ok and type(value) == "number" then
        return value
    end
    return nil
end

local function safeRobloxMemoryMb()
    local ok, value = pcall(function()
        return Stats:GetTotalMemoryUsageMb()
    end)
    if ok and type(value) == "number" then
        return value
    end
    return nil
end

local function safeText(callback)
    local ok, value = pcall(callback)
    if ok and value ~= nil then
        return tostring(value)
    end
    return "unavailable"
end

local function copyAndSort(values, count)
    local sorted = table.create(count)
    for index = 1, count do
        sorted[index] = values[index]
    end
    table.sort(sorted)
    return sorted
end

local function percentile(sorted, percentileValue)
    local index = math.clamp(math.ceil(#sorted * percentileValue), 1, #sorted)
    return sorted[index]
end

local function summarize(values, count)
    local sorted = copyAndSort(values, count)
    local total = 0
    for index = 1, count do
        total += values[index]
    end
    return {
        average = total / count,
        median = percentile(sorted, 0.5),
        p95 = percentile(sorted, 0.95),
        p99 = percentile(sorted, 0.99),
        best = sorted[1],
        worst = sorted[count],
    }
end

local function summarizeRange(values, firstIndex, lastIndex)
    local count = lastIndex - firstIndex + 1
    local selected = table.create(count)
    for index = 1, count do
        selected[index] = values[firstIndex + index - 1]
    end
    return summarize(selected, count)
end

local function countHitches(frameSamples, count)
    local hitches = {}
    for _, threshold in HITCH_THRESHOLDS do
        hitches[threshold.label] = 0
    end
    for index = 1, count do
        local frameMs = frameSamples[index]
        for _, threshold in HITCH_THRESHOLDS do
            if frameMs > threshold.milliseconds then
                hitches[threshold.label] += 1
            end
        end
    end
    return hitches
end

local function measure(profile, workloadName)
    local sampleCount = RUN_COUNT * MEASURE_FRAMES
    local coldVmSamples = table.create(RUN_COUNT)
    local coldFrameSamples = table.create(RUN_COUNT)
    local warmVmSamples = table.create(sampleCount)
    local frameSamples = table.create(sampleCount)
    local runMedians = table.create(RUN_COUNT)
    local luaMemoryBefore = safeLuaMemoryKb()
    local robloxMemoryBefore = safeRobloxMemoryMb()
    local checksum = 0
    local frameCount = 0
    local sampleIndex = 0

    for run = 1, RUN_COUNT do
        RunService.Heartbeat:Wait()
        frameCount += 1

        local coldStarted = os.clock()
        local createSuite = profile.factory()
        local suite = createSuite()
        local workload = suite[workloadName]
        assert(type(workload) == "function", "missing workload: " .. workloadName)
        checksum += workload(1)
        coldVmSamples[run] = (os.clock() - coldStarted) * 1000

        local coldFrameDelta = RunService.Heartbeat:Wait()
        frameCount += 1
        coldFrameSamples[run] = coldFrameDelta * 1000

        for warmupFrame = 1, WARMUP_FRAMES do
            checksum += workload(warmupFrame + 1)
            RunService.Heartbeat:Wait()
            frameCount += 1
        end

        local firstRunSample = sampleIndex + 1
        for measuredFrame = 1, MEASURE_FRAMES do
            local started = os.clock()
            checksum += workload(WARMUP_FRAMES + measuredFrame + 1)
            local elapsedMs = (os.clock() - started) * 1000
            local actualFrameDelta = RunService.Heartbeat:Wait()
            frameCount += 1

            sampleIndex += 1
            warmVmSamples[sampleIndex] = elapsedMs
            frameSamples[sampleIndex] = actualFrameDelta * 1000
        end
        runMedians[run] = summarizeRange(warmVmSamples, firstRunSample, sampleIndex).median
    end

    local luaMemoryAfter = safeLuaMemoryKb()
    local robloxMemoryAfter = safeRobloxMemoryMb()
    local warmVm = summarize(warmVmSamples, sampleCount)
    local actualFrame = summarize(frameSamples, sampleCount)
    local coldVm = summarize(coldVmSamples, RUN_COUNT)
    local coldFrame = summarize(coldFrameSamples, RUN_COUNT)
    local runMedianSummary = summarize(runMedians, RUN_COUNT)

    return {
        profile = profile.name,
        workload = workloadName,
        checksum = checksum,
        sampleCount = sampleCount,
        frameCount = frameCount,
        coldVm = coldVm,
        coldFrame = coldFrame,
        warmVm = warmVm,
        actualFrame = actualFrame,
        runMedianBest = runMedianSummary.best,
        runMedianMedian = runMedianSummary.median,
        runMedianWorst = runMedianSummary.worst,
        fps = actualFrame.average > 0 and 1000 / actualFrame.average or 0,
        hitches = countHitches(frameSamples, sampleCount),
        luaMemoryBefore = luaMemoryBefore,
        luaMemoryAfter = luaMemoryAfter,
        luaMemoryDelta = luaMemoryBefore and luaMemoryAfter and luaMemoryAfter - luaMemoryBefore or nil,
        robloxMemoryBefore = robloxMemoryBefore,
        robloxMemoryAfter = robloxMemoryAfter,
        robloxMemoryDelta = robloxMemoryBefore and robloxMemoryAfter and robloxMemoryAfter - robloxMemoryBefore or nil,
    }
end

local function rate(result, hitchLabel)
    return result.hitches[hitchLabel] * 100 / result.sampleCount
end

local function positiveExcess(value, baseline)
    return math.max(0, value - baseline)
end

local function exceedsBoundary(result, plain, boundary)
    local coldFrameExcess = positiveExcess(result.coldFrame.worst, plain.coldFrame.worst)
    local frameP95Excess = positiveExcess(result.actualFrame.p95, plain.actualFrame.p95)
    local frameP99Excess = positiveExcess(result.actualFrame.p99, plain.actualFrame.p99)
    local hitch33Excess = positiveExcess(rate(result, "Hitch33"), rate(plain, "Hitch33"))
    local hitch50Excess = positiveExcess(rate(result, "Hitch50"), rate(plain, "Hitch50"))

    return result.coldVm.median > boundary.coldVm
        or result.warmVm.p95 > boundary.warmP95
        or (result.coldFrame.worst > boundary.coldFrame and coldFrameExcess > boundary.coldFrameExcess)
        or (result.actualFrame.p95 > boundary.frameP95 and frameP95Excess > boundary.frameP95Excess)
        or (result.actualFrame.p99 > boundary.frameP99 and frameP99Excess > boundary.frameP99Excess)
        or (rate(result, "Hitch33") > boundary.hitch33Rate and hitch33Excess > boundary.hitch33Excess)
        or (rate(result, "Hitch50") > boundary.hitch50Rate and hitch50Excess > boundary.hitch50Excess)
end

local function classify(result, plain)
    local criteria = TIER_CRITERIA[DEVICE_TIER]
    if exceedsBoundary(result, plain, criteria.warning) then
        return "FAIL"
    end
    if exceedsBoundary(result, plain, criteria.acceptable) then
        return "WARNING"
    end
    return "ACCEPTABLE"
end

local function safeRatio(numerator, denominator)
    if denominator == 0 then
        return nil
    end
    return numerator / denominator
end

local deviceInfo = {
    platform = safeText(function()
        return UserInputService:GetPlatform()
    end),
    input = UserInputService.TouchEnabled and "TOUCH" or (UserInputService.KeyboardEnabled and "KEYBOARD" or "OTHER"),
    touch = tostring(UserInputService.TouchEnabled),
    keyboard = tostring(UserInputService.KeyboardEnabled),
    gamepad = tostring(UserInputService.GamepadEnabled),
    viewport = safeText(function()
        local camera = Workspace.CurrentCamera
        return camera and (tostring(math.floor(camera.ViewportSize.X)) .. "x" .. tostring(math.floor(camera.ViewportSize.Y))) or "unavailable"
    end),
    graphics = safeText(function()
        return UserSettings():GetService("UserGameSettings").SavedQualityLevel
    end),
    executor = "not-queried",
    timestamp = safeText(function()
        return DateTime.now():ToIsoDate()
    end),
    session = safeText(function()
        return HttpService:GenerateGUID(false)
    end),
}

print("INTERIUM_MOBILE_BENCHMARK_RUNNING|Expected=5-11min|KeepClientForeground=true|DoNotInteract=true")
for _ = 1, 3 do
    RunService.Heartbeat:Wait()
end

local idleResult = measure({ name = "IDLE", factory = makeIdle }, "idle")
local results = {}
local byWorkload = {}

for _, workloadName in WORKLOADS do
    local workloadResults = {}
    byWorkload[workloadName] = workloadResults
    for _, profile in PROFILES do
        local result = measure(profile, workloadName)
        table.insert(results, result)
        workloadResults[profile.name] = result
    end
end

local function number(value, decimals)
    if value == nil then
        return "unavailable"
    end
    return string.format("%." .. tostring(decimals or 3) .. "f", value)
end

local function resultLine(result, gate)
    return table.concat({
        "RESULT",
        "Workload=" .. result.workload,
        "Profile=" .. result.profile,
        "Gate=" .. gate,
        "ColdMs=" .. number(result.coldVm.median),
        "ColdBestMs=" .. number(result.coldVm.best),
        "ColdWorstMs=" .. number(result.coldVm.worst),
        "ColdFrameMedianMs=" .. number(result.coldFrame.median),
        "ColdFrameWorstMs=" .. number(result.coldFrame.worst),
        "WarmAvgMs=" .. number(result.warmVm.average),
        "WarmMedianMs=" .. number(result.warmVm.median),
        "WarmP95Ms=" .. number(result.warmVm.p95),
        "WarmP99Ms=" .. number(result.warmVm.p99),
        "WarmWorstMs=" .. number(result.warmVm.worst),
        "RunMedianBestMs=" .. number(result.runMedianBest),
        "RunMedianMedianMs=" .. number(result.runMedianMedian),
        "RunMedianWorstMs=" .. number(result.runMedianWorst),
        "FrameAvgMs=" .. number(result.actualFrame.average),
        "FrameMedianMs=" .. number(result.actualFrame.median),
        "FrameP95Ms=" .. number(result.actualFrame.p95),
        "FrameP99Ms=" .. number(result.actualFrame.p99),
        "WorstFrameMs=" .. number(result.actualFrame.worst),
        "FPS=" .. number(result.fps, 2),
        "FrameCount=" .. tostring(result.frameCount),
        "SampleCount=" .. tostring(result.sampleCount),
        "Hitch16=" .. tostring(result.hitches.Hitch16),
        "Hitch20=" .. tostring(result.hitches.Hitch20),
        "Hitch25=" .. tostring(result.hitches.Hitch25),
        "Hitch33=" .. tostring(result.hitches.Hitch33),
        "Hitch50=" .. tostring(result.hitches.Hitch50),
        "Hitch100=" .. tostring(result.hitches.Hitch100),
        "LuaMemoryBeforeKB=" .. number(result.luaMemoryBefore),
        "LuaMemoryAfterKB=" .. number(result.luaMemoryAfter),
        "LuaMemoryDeltaKB=" .. number(result.luaMemoryDelta),
        "RobloxMemoryBeforeMB=" .. number(result.robloxMemoryBefore),
        "RobloxMemoryAfterMB=" .. number(result.robloxMemoryAfter),
        "RobloxMemoryDeltaMB=" .. number(result.robloxMemoryDelta),
        "Checksum=" .. number(result.checksum, 0),
    }, "|")
end

local lines = table.create(64)
table.insert(lines, "INTERIUM_MOBILE_RESULT_BEGIN")
table.insert(lines, table.concat({
    "META",
    "Build=" .. BUILD_LABEL,
    "Tier=" .. DEVICE_TIER,
    "Platform=" .. deviceInfo.platform,
    "Input=" .. deviceInfo.input,
    "Touch=" .. deviceInfo.touch,
    "Keyboard=" .. deviceInfo.keyboard,
    "Gamepad=" .. deviceInfo.gamepad,
    "Viewport=" .. deviceInfo.viewport,
    "Graphics=" .. deviceInfo.graphics,
    "Executor=" .. deviceInfo.executor,
    "Timestamp=" .. deviceInfo.timestamp,
    "Session=" .. deviceInfo.session,
    "Runs=" .. tostring(RUN_COUNT),
    "Phases=COLD,WARMUP,WARM_MEASUREMENT",
    "WarmupFrames=" .. tostring(WARMUP_FRAMES),
    "MeasureFrames=" .. tostring(MEASURE_FRAMES),
    "GCProxy=LuaHeapKB",
}, "|"))

local activeCriteria = TIER_CRITERIA[DEVICE_TIER]
for _, boundaryName in { "acceptable", "warning" } do
    local boundary = activeCriteria[boundaryName]
    table.insert(lines, table.concat({
        "CRITERIA",
        "Tier=" .. DEVICE_TIER,
        "Boundary=" .. string.upper(boundaryName),
        "ColdVmMs=" .. number(boundary.coldVm),
        "WarmP95Ms=" .. number(boundary.warmP95),
        "ColdFrameMs=" .. number(boundary.coldFrame),
        "ColdFrameExcessMs=" .. number(boundary.coldFrameExcess),
        "FrameP95Ms=" .. number(boundary.frameP95),
        "FrameP95ExcessMs=" .. number(boundary.frameP95Excess),
        "FrameP99Ms=" .. number(boundary.frameP99),
        "FrameP99ExcessMs=" .. number(boundary.frameP99Excess),
        "Hitch33RatePct=" .. number(boundary.hitch33Rate),
        "Hitch33ExcessPct=" .. number(boundary.hitch33Excess),
        "Hitch50RatePct=" .. number(boundary.hitch50Rate),
        "Hitch50ExcessPct=" .. number(boundary.hitch50Excess),
    }, "|"))
end

table.insert(lines, resultLine(idleResult, "BASELINE"))
local overallRank = 1
local rank = { ACCEPTABLE = 1, WARNING = 2, FAIL = 3 }

for _, workloadName in WORKLOADS do
    local workloadResults = byWorkload[workloadName]
    local plain = workloadResults.PLAIN
    table.insert(lines, resultLine(plain, "BASELINE"))
    for _, profileName in { "BALANCED", "STRONG" } do
        local result = workloadResults[profileName]
        local gate = classify(result, plain)
        overallRank = math.max(overallRank, rank[gate])
        table.insert(lines, resultLine(result, gate))
    end

    local balanced = workloadResults.BALANCED
    local strong = workloadResults.STRONG
    table.insert(lines, table.concat({
        "RATIO",
        "Workload=" .. workloadName,
        "BalancedVsPlainWarmMedian=" .. number(safeRatio(balanced.warmVm.median, plain.warmVm.median)),
        "StrongVsPlainWarmMedian=" .. number(safeRatio(strong.warmVm.median, plain.warmVm.median)),
        "StrongVsBalancedWarmMedian=" .. number(safeRatio(strong.warmVm.median, balanced.warmVm.median)),
        "BalancedVsPlainCold=" .. number(safeRatio(balanced.coldVm.median, plain.coldVm.median)),
        "StrongVsPlainCold=" .. number(safeRatio(strong.coldVm.median, plain.coldVm.median)),
    }, "|"))
end

local overallGate = overallRank == 3 and "FAIL" or (overallRank == 2 and "WARNING" or "ACCEPTABLE")
table.insert(lines, "SUMMARY|Tier=" .. DEVICE_TIER .. "|ObjectiveGate=" .. overallGate .. "|Scope=P2_MOBILE_CANDIDATE_REVIEW_REQUIRED")
table.insert(lines, "INTERIUM_MOBILE_RESULT_END")

local finalOutput = table.concat(lines, "\n")
print(finalOutput)

return {
    buildLabel = BUILD_LABEL,
    deviceTier = DEVICE_TIER,
    idle = idleResult,
    results = results,
    objectiveGate = overallGate,
    output = finalOutput,
}
